	public static string BuildDocument(DesktopAccountResponse account, StoreWebHomeContext context)
	{
		return $"<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n<title>Nạp ví NestG</title>\r\n<style>{BuildStyles()}{StoreWarpHeaderHtml.Styles}{StoreWindowsUpdateHeaderHtml.Styles}{StoreSteamConnectionHeaderHtml.Styles}{StoreSupportContactHeaderHtml.Styles}</style>\r\n</head>\r\n<body data-min-amount=\"{account.MinimumTopUpAmount.ToString("0", CultureInfo.InvariantCulture)}\"\r\n      data-max-amount=\"{account.MaximumTopUpAmount.ToString("0", CultureInfo.InvariantCulture)}\">\r\n<div class=\"wallet-shell\">\r\n    <header class=\"wallet-chrome\" data-drag-region>\r\n        <div class=\"nestg-brand-warp\">\r\n            <div class=\"brand-cluster\">\r\n                <span class=\"brand-mark\">N</span>\r\n                <span class=\"brand-copy\">\r\n                    <strong>NestG</strong>\r\n                    <small>Wallet Top-up</small>\r\n                </span>\r\n            </div>\r\n            {StoreWarpHeaderHtml.Render()}\r\n            {StoreWindowsUpdateHeaderHtml.Render()}\r\n            {StoreSteamConnectionHeaderHtml.Render()}\r\n        </div>\r\n        <nav class=\"wallet-nav\">\r\n            <button type=\"button\" data-host-action=\"backHome\">Cửa hàng</button>\r\n            <button type=\"button\" data-host-action=\"openProfile\">Cá nhân</button>\r\n        </nav>\r\n        <div class=\"nestg-header-account\">\r\n            {StoreSupportContactHeaderHtml.Render()}\r\n            {StoreAccountMenuHtml.Build(account, "wallet", context.NotificationUnreadCount)}\r\n        </div>\r\n        <div class=\"window-controls\">\r\n            <button type=\"button\" class=\"window-button\" data-host-action=\"minimize\" aria-label=\"Thu nhỏ cửa sổ\">-</button>\r\n            <button type=\"button\" class=\"window-button\" data-host-action=\"toggleMaximize\" aria-label=\"Phóng to hoặc khôi phục cửa sổ\">&#9633;</button>\r\n            <button type=\"button\" class=\"window-button is-close\" data-host-action=\"close\" aria-label=\"Đóng cửa sổ\">&#215;</button>\r\n        </div>\r\n    </header>\r\n\r\n    <main class=\"wallet-content\">\r\n        <section class=\"topup-card\">\r\n            <div class=\"summary-panel\">\r\n                <span class=\"eyebrow\">NESTG WALLET</span>\r\n                <h1>Nạp ví</h1>\r\n                <p>Tạo phiếu nạp SePay trong launcher. Sau khi chuyển khoản thành công, số dư ví sẽ được cập nhật tự động.</p>\r\n                <div class=\"balance-box\">\r\n                    <span>Số dư hiện tại</span>\r\n                    <strong>{Html(account.WalletBalanceText)}</strong>\r\n                    <small>Trạng thái: {Html(account.WalletStatusText)}</small>\r\n                </div>\r\n                <div class=\"limit-grid\">\r\n                    <div><span>Tối thiểu</span><strong>{Html(FormatAmount(account.MinimumTopUpAmount))}</strong></div>\r\n                    <div><span>Tối đa mỗi lần</span><strong>{Html(FormatAmount(account.MaximumTopUpAmount))}</strong></div>\r\n                </div>\r\n            </div>\r\n\r\n            <form class=\"topup-panel\" data-topup-form novalidate>\r\n                <span class=\"panel-kicker\">Tạo mã QR</span>\r\n                <h2>Chọn số tiền cần nạp</h2>\r\n                <p class=\"panel-copy\">Chọn nhanh hoặc nhập số tiền VND. Launcher sẽ mở QR SePay để bạn thanh toán.</p>\r\n\r\n                <div class=\"quick-grid\">\r\n                    {RenderQuickAmounts(account.QuickAmounts)}\r\n                </div>\r\n\r\n                <label class=\"amount-field\">\r\n                    <span>Số tiền nạp</span>\r\n                    <div class=\"input-shell\">\r\n                        <input name=\"amount\" type=\"text\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Nhập số tiền VND\" />\r\n                        <strong>VND</strong>\r\n                    </div>\r\n                </label>\r\n\r\n                <p class=\"status\" data-status aria-live=\"polite\"></p>\r\n                <button type=\"submit\" class=\"submit-button\" data-submit>Tạo phiếu nạp tiền</button>\r\n\r\n                <div class=\"safe-note\">\r\n                    <span>i</span>\r\n                    <p>Không tắt launcher trong lúc QR đang mở. Nếu giao dịch chưa cập nhật ngay, hãy bấm làm mới trạng thái trong cửa sổ QR.</p>\r\n                </div>\r\n            </form>\r\n        </section>\r\n    </main>\r\n\r\n    <div class=\"toast-host\" data-toast-host></div>\r\n</div>\r\n<div class=\"qr-modal\" data-qr-modal hidden>\r\n    <div class=\"qr-backdrop\" data-qr-close></div>\r\n    <section class=\"qr-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"qr-title\">\r\n        <div class=\"qr-dialog-head\">\r\n            <div>\r\n                <span class=\"panel-kicker\">SEPAY QR</span>\r\n                <h2 id=\"qr-title\">Quét mã để nạp ví</h2>\r\n            </div>\r\n            <button type=\"button\" class=\"qr-close\" data-qr-close aria-label=\"Đóng\">×</button>\r\n        </div>\r\n        <div class=\"qr-dialog-body\">\r\n            <div class=\"qr-left\">\r\n                <div class=\"qr-image-box\">\r\n                    <img data-qr-image alt=\"QR nạp ví NestG\" />\r\n                    <div class=\"qr-image-fallback\" data-qr-image-fallback hidden>Không thể tải QR</div>\r\n                </div>\r\n                <div class=\"qr-amount\">\r\n                    <span>Tổng cần thanh toán</span>\r\n                    <strong data-qr-total></strong>\r\n                </div>\r\n                <div class=\"qr-status\" data-qr-status>\r\n                    <strong data-qr-status-title></strong>\r\n                    <span data-qr-status-description></span>\r\n                </div>\r\n            </div>\r\n            <div class=\"qr-right\">\r\n                <div class=\"transfer-card\">\r\n                    <h3>Thông tin chuyển khoản</h3>\r\n                    <dl>\r\n                        <dt>Ngân hàng</dt><dd data-qr-bank></dd>\r\n                        <dt>Số tài khoản</dt><dd data-qr-account-number></dd>\r\n                        <dt>Chủ tài khoản</dt><dd data-qr-account-name></dd>\r\n                        <dt>Nội dung CK</dt><dd data-qr-transfer-content></dd>\r\n                        <dt>Mã giao dịch</dt><dd data-qr-order-code></dd>\r\n                        <dt>Hết hạn</dt><dd data-qr-expires></dd>\r\n                    </dl>\r\n                </div>\r\n                <div class=\"qr-actions\">\r\n                    <button type=\"button\" class=\"secondary-command\" data-qr-refresh>Làm mới trạng thái</button>\r\n                    <button type=\"button\" class=\"primary-command\" data-qr-close>Thoát</button>\r\n                </div>\r\n                <p class=\"qr-note\">Chuyển đúng số tiền và nội dung để hệ thống tự động cộng số dư ví.</p>\r\n            </div>\r\n        </div>\r\n        <div class=\"payment-success-popup\" data-payment-success hidden>\r\n            <div class=\"payment-success-icon\">&#10003;</div>\r\n            <span class=\"panel-kicker\">NESTG WALLET</span>\r\n            <h2 data-payment-success-title>Bạn đã thanh toán thành công</h2>\r\n            <p data-payment-success-message>Tiền đã được cộng vào ví NestG của bạn.</p>\r\n            <div class=\"payment-success-balance\">\r\n                <span>Số dư hiện tại</span>\r\n                <strong data-payment-success-balance></strong>\r\n            </div>\r\n            <button type=\"button\" class=\"primary-command payment-success-confirm\" data-payment-success-confirm>\r\n                Xác thực\r\n            </button>\r\n        </div>\r\n    </section>\r\n</div>\r\n{BuildLoadingOverlay()}\r\n<script>{BuildScript()}</script>\r\n</body>\r\n</html>";
