	private static string RenderQuickAmounts(IReadOnlyList<DesktopAccountWalletQuickAmountResponse> quickAmounts)
	{
		IReadOnlyList<DesktopAccountWalletQuickAmountResponse> readOnlyList2;
		if (quickAmounts.Count <= 0)
		{
			IReadOnlyList<DesktopAccountWalletQuickAmountResponse> readOnlyList = new _003C_003Ez__ReadOnlyArray<DesktopAccountWalletQuickAmountResponse>(new DesktopAccountWalletQuickAmountResponse[4]
			{
				new DesktopAccountWalletQuickAmountResponse
				{
					Amount = 50000m,
					AmountText = FormatAmount(50000m)
				},
				new DesktopAccountWalletQuickAmountResponse
				{
					Amount = 100000m,
					AmountText = FormatAmount(100000m)
				},
				new DesktopAccountWalletQuickAmountResponse
				{
					Amount = 200000m,
					AmountText = FormatAmount(200000m)
				},
				new DesktopAccountWalletQuickAmountResponse
				{
					Amount = 500000m,
					AmountText = FormatAmount(500000m)
				}
			});
			readOnlyList2 = readOnlyList;
		}
		else
		{
			readOnlyList2 = quickAmounts;
		}
		StringBuilder stringBuilder = new StringBuilder();
		foreach (DesktopAccountWalletQuickAmountResponse item in readOnlyList2)
		{
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(73, 2, stringBuilder2);
			handler.AppendLiteral("<button type=\"button\" class=\"quick-button\" data-quick-amount=\"");
			handler.AppendFormatted(item.Amount.ToString("0", CultureInfo.InvariantCulture));
			handler.AppendLiteral("\">");
			handler.AppendFormatted(Html(item.AmountText));
			handler.AppendLiteral("</button>");
			stringBuilder2.Append(ref handler);
		}
		return stringBuilder.ToString();
	}

