.brand-copy strong { font-size: 16px; letter-spacing: .02em; }\r\n.brand-copy small { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: .12em; }\r\n.wallet-nav {\r\n    justify-self: center;\r\n    gap: 8px;\r\n    padding: 4px;\r\n    border: 1px solid rgba(102, 192, 244, .12);\r\n    border-radius: 999px;\r\n    background: rgba(8, 22, 34, .82);\r\n}\r\n.wallet-nav button {\r\n    min-height: 34px;\r\n    padding: 0 15px;\r\n    border: 0;\r\n    border-radius: 999px;\r\n    background: transparent;\r\n    color: #b8d3e5;\r\n    font-size: 12px;\r\n    font-weight: 800;\r\n}\r\n.wallet-nav button:hover,\r\n.wallet-nav button:focus-visible {\r\n    outline: 0;\r\n    background: rgba(102, 192, 244, .13);\r\n    color: #f2fbff;\r\n}\r\n" + StoreAccountMenuHtml.Styles + "\r\n.window-controls { display: flex; gap: 4px; }\r\n.window-button {\r\n    width: 32px;\r\n    height: 28px;\r\n    border: 0;\r\n    border-radius: 4px;\r\n    background: transparent;\r\n    color: #cfd9e6;\r\n}\r\n.window-button:hover { background: rgba(255, 255, 255, .08); }\r\n.window-button.is-close:hover { background: #c83232; color: #fff; }\r\n.wallet-content {\r\n    width: min(1180px, calc(100vw - 54px));\r\n    margin: 34px auto 0;\r\n}\r\n.topup-card {\r\n    display: grid;\r\n    grid-template-columns: minmax(0, .92fr) minmax(420px, 1.08fr);\r\n    gap: 18px;\r\n    align-items: stretch;\r\n}\r\n.summary-panel,\r\n.topup-panel {\r\n    border: 1px solid rgba(102, 192, 244, .2);\r\n    border-radius: 8px;\r\n    background: linear-gradient(180deg, rgba(15, 35, 52, .96), rgba(7, 18, 28, .98));\r\n    box-shadow: 0 20px 50px rgba(0, 0, 0, .3);\r\n}\r\n.summary-panel {\r\n    padding: 28px;\r\n    background:\r\n        radial-gradient(circle at 18% 18%, rgba(102, 192, 244, .16), transparent 34%),\r\n        linear-gradient(135deg, rgba(20, 51, 78, .98), rgba(8, 20, 31, .96));\r\n}\r\n.eyebrow,\r\n.panel-kicker {\r\n    color: var(--cyan);\r\n    font-size: 11px;\r\n    font-weight: 950;\r\n    letter-spacing: .16em;\r\n}\r\n.summary-panel h1 {\r\n    margin: 12px 0 10px;\r\n    color: #f4fbff;\r\n    font-size: clamp(42px, 6vw, 72px);\r\n    line-height: .95;\r\n    letter-spacing: -.055em;\r\n}\r\n.summary-panel p,\r\n.panel-copy {\r\n    margin: 0;\r\n    color: #9fb7cc;\r\n    font-size: 14px;\r\n    line-height: 1.6;\r\n}\r\n.balance-box {\r\n    margin-top: 28px;\r\n    padding: 22px;\r\n    border: 1px solid rgba(155, 211, 61, .24);\r\n    border-radius: 7px;\r\n    background:\r\n        radial-gradient(circle at 86% 16%, rgba(155, 211, 61, .16), transparent 32%),\r\n        rgba(8, 24, 23, .76);\r\n}\r\n.balance-box span,\r\n.limit-grid span {\r\n    color: #93aa9e;\r\n    font-size: 11px;\r\n    font-weight: 900;\r\n    letter-spacing: .08em;\r\n    text-transform: uppercase;\r\n}\r\n.balance-box strong {\r\n    display: block;\r\n    margin-top: 8px;\r\n    color: #dfffb5;\r\n    font-size: 38px;\r\n    line-height: 1;\r\n}\r\n.balance-box small {\r\n    display: block;\r\n    margin-top: 10px;\r\n    color: #8fa99d;\r\n    font-size: 12px;\r\n}\r\n.limit-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(2, minmax(0, 1fr));\r\n    gap: 12px;\r\n    margin-top: 14px;\r\n}\r\n.limit-grid div {\r\n    padding: 15px;\r\n    border: 1px solid rgba(102, 192, 244, .13);\r\n    border-radius: 6px;\r\n    background: rgba(5, 16, 25, .5);\r\n}\r\n.limit-grid strong {\r\n    display: block;\r\n    margin-top: 6px;\r\n    color: #eaf7ff;\r\n    font-size: 17px;\r\n}\r\n.topup-panel {\r\n    padding: 28px;\r\n}\r\n.topup-panel h2 {\r\n    margin: 8px 0 8px;\r\n    color: #f4fbff;\r\n    font-size: 30px;\r\n    line-height: 1.1;\r\n    letter-spacing: -.03em;\r\n}\r\n.quick-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(2, minmax(0, 1fr));\r\n    gap: 10px;\r\n    margin-top: 22px;\r\n}\r\n.quick-button {\r\n    min-height: 48px;\r\n    border: 1px solid rgba(102, 192, 244, .17);\r\n    border-radius: 5px;\r\n    background: rgba(102, 192, 244, .07);\r\n    color: #dff4ff;\r\n    font-size: 13px;\r\n    font-weight: 900;\r\n}\r\n.quick-button:hover,\r\n.quick-button:focus-visible,\r\n.quick-button.is-selected {\r\n    outline: 0;\r\n    border-color: rgba(155, 211, 61, .48);\r\n    background: rgba(155, 211, 61, .13);\r\n    color: #eaffc8;\r\n}\r\n.amount-field {\r\n    display: grid;\r\n    gap: 8px;\r\n    margin-top: 20px;\r\n}\r\n.amount-field > span {\r\n    color: #aabcc9;\r\n    font-size: 11px;\r\n    font-weight: 850;\r\n    letter-spacing: .06em;\r\n    text-transform: uppercase;\r\n}\r\n.input-shell {\r\n    position: relative;\r\n}\r\n.input-shell input {\r\n    width: 100%;\r\n    height: 54px;\r\n    border: 1px solid rgba(86, 128, 160, .42);\r\n    border-radius: 5px;\r\n    outline: 0;\r\n    background: rgba(5, 17, 25, .82);\r\n    color: #eef6fc;\r\n    padding: 0 76px 0 15px;\r\n    caret-color: var(--cyan);\r\n    font-size: 18px;\r\n    font-weight: 850;\r\n}\r\n.input-shell input:focus {\r\n    border-color: rgba(102, 192, 244, .82);\r\n    box-shadow: 0 0 0 3px rgba(102, 192, 244, .09);\r\n}\r\n.input-shell strong {\r\n    position: absolute;\r\n    right: 14px;\r\n    top: 50%;\r\n    color: #8fadc1;\r\n    font-size: 12px;\r\n    transform: translateY(-50%);\r\n}\r\n.status {\r\n    min-height: 20px;\r\n    margin: 14px 0 0;\r\n    color: #91c8e8;\r\n    font-size: 12px;\r\n    line-height: 1.45;\r\n}\r\n.status.is-error { color: var(--red); }\r\n.submit-button {\r\n    width: 100%;\r\n    min-height: 52px;\r\n    margin-top: 8px;\r\n    border: 1px solid rgba(190, 240, 111, .24);\r\n    border-radius: 5px;\r\n    background: linear-gradient(180deg, #9bd33d 0%, #75a920 100%);\r\n    color: #fff;\r\n    cursor: pointer;\r\n    font-size: 13px;\r\n    font-weight: 950;\r\n    box-shadow: 0 10px 24px rgba(89, 132, 28, .2);\r\n}\r\n.submit-button:disabled {\r\n    cursor: wait;\r\n    opacity: .68;\r\n}\r\n.safe-note {\r\n    display: grid;\r\n    grid-template-columns: 28px minmax(0, 1fr);\r\n    gap: 11px;\r\n    margin-top: 16px;\r\n    padding: 13px;\r\n    border: 1px solid rgba(102, 192, 244, .13);\r\n    border-radius: 5px;\r\n    background: rgba(102, 192, 244, .05);\r\n}\r\n.safe-note span {\r\n    width: 28px;\r\n    height: 28px;\r\n    display: grid;\r\n    place-items: center;\r\n    border-radius: 50%;\r\n    background: rgba(102, 192, 244, .13);\r\n    color: #aee6ff;\r\n    font-weight: 950;\r\n}\r\n.safe-note p {\r\n    margin: 0;\r\n    color: #8fa6b8;\r\n    font-size: 12px;\r\n    line-height: 1.45;\r\n}\r\n.toast-host {\r\n    position: fixed;\r\n    right: 22px;\r\n    bottom: 22px;\r\n    z-index: 50;\r\n    display: grid;\r\n    gap: 10px;\r\n}\r\n.toast {\r\n    max-width: 360px;\r\n    padding: 13px 15px;\r\n    border: 1px solid rgba(102, 192, 244, .25);\r\n    border-radius: 5px;\r\n    background: rgba(9, 23, 34, .96);\r\n    color: #dff2ff;\r\n    box-shadow: 0 18px 36px rgba(0, 0, 0, .32);\r\n    font-size: 13px;\r\n}\r\n.qr-modal {\r\n    position: fixed;\r\n    inset: 0;\r\n    z-index: 80;\r\n    display: grid;\r\n    place-items: center;\r\n    padding: 26px;\r\n}\r\n.qr-backdrop {\r\n    position: absolute;\r\n    inset: 0;\r\n    background: rgba(2, 7, 12, .68);\r\n    backdrop-filter: blur(10px);\r\n}\r\n.qr-dialog {\r\n    position: relative;\r\n    width: min(980px, calc(100vw - 64px));\r\n    max-height: calc(100vh - 64px);\r\n    overflow: auto;\r\n    border: 1px solid rgba(102, 192, 244, .28);\r\n    border-radius: 9px;\r\n    background:\r\n        radial-gradient(circle at 16% 18%, rgba(102, 192, 244, .12), transparent 30%),\r\n        linear-gradient(180deg, rgba(15, 35, 52, .99), rgba(6, 16, 25, .99));\r\n    box-shadow: 0 34px 90px rgba(0, 0, 0, .48);\r\n}\r\n.payment-success-popup {\r\n    position: absolute;\r\n    inset: 0;\r\n    z-index: 4;\r\n    min-height: 480px;\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    padding: 42px;\r\n    text-align: center;\r\n    background:\r\n        radial-gradient(circle at 50% 30%, rgba(155, 211, 61, .16), transparent 32%),\r\n        linear-gradient(180deg, rgba(15, 35, 52, .995), rgba(6, 16, 25, .995));\r\n}\r\n.payment-success-icon {\r\n    width: 76px;\r\n    height: 76px;\r\n    display: grid;\r\n    place-items: center;\r\n    margin-bottom: 18px;\r\n    border: 1px solid rgba(155, 211, 61, .52);\r\n    border-radius: 50%;\r\n    background: rgba(155, 211, 61, .14);\r\n    color: #dfffb5;\r\n    font-size: 38px;\r\n    font-weight: 950;\r\n    box-shadow: 0 0 42px rgba(155, 211, 61, .15);\r\n}\r\n.payment-success-popup h2 {\r\n    margin: 10px 0 8px;\r\n    color: #f4fbff;\r\n    font-size: 32px;\r\n}\r\n.payment-success-popup > p {\r\n    margin: 0;\r\n    color: #a9bdcc;\r\n    font-size: 14px;\r\n}\r\n.payment-success-balance {\r\n    min-width: 300px;\r\n    margin-top: 24px;\r\n    padding: 18px 24px;\r\n    border: 1px solid rgba(155, 211, 61, .28);\r\n    border-radius: 7px;\r\n    background: rgba(12, 32, 26, .78);\r\n}\r\n.payment-success-balance span {\r\n    display: block;\r\n    color: #9cb5a8;\r\n    font-size: 11px;\r\n    font-weight: 900;\r\n    letter-spacing: .08em;\r\n    text-transform: uppercase;\r\n}\r\n.payment-success-balance strong {\r\n    display: block;\r\n    margin-top: 7px;\r\n    color: #dfffb5;\r\n    font-size: 32px;\r\n}\r\n.payment-success-confirm {\r\n    min-width: 220px;\r\n    margin-top: 22px;\r\n}\r\n.qr-dialog-head {\r\n    min-height: 78px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    gap: 18px;\r\n    padding: 20px 22px;\r\n    border-bottom: 1px solid rgba(102, 192, 244, .13);\r\n}\r\n.qr-dialog-head h2 {\r\n    margin: 5px 0 0;\r\n    color: #f4fbff;\r\n    font-size: 26px;\r\n    line-height: 1.1;\r\n}\r\n.qr-close {\r\n    width: 36px;\r\n    height: 36px;\r\n    border: 1px solid rgba(255, 255, 255, .08);\r\n    border-radius: 5px;\r\n    background: rgba(255, 255, 255, .04);\r\n    color: #d7e9f5;\r\n    font-size: 22px;\r\n}\r\n.qr-close:hover { background: #c83232; color: #fff; }\r\n.qr-dialog-body {\r\n    display: grid;\r\n    grid-template-columns: 330px minmax(0, 1fr);\r\n    gap: 18px;\r\n    padding: 22px;\r\n}\r\n.qr-left,\r\n.transfer-card {\r\n    border: 1px solid rgba(102, 192, 244, .14);\r\n    border-radius: 7px;\r\n    background: rgba(5, 16, 25, .58);\r\n}\r\n.qr-left { padding: 18px; }\r\n.qr-image-box {\r\n    position: relative;\r\n    display: grid;\r\n    place-items: center;\r\n    padding: 14px;\r\n    border: 1px solid rgba(102, 192, 244, .2);\r\n    border-radius: 7px;\r\n    background: #fff;\r\n}\r\n.qr-image-box img {\r\n    width: min(260px, 100%);\r\n    aspect-ratio: 1;\r\n    object-fit: contain;\r\n}\r\n.qr-image-fallback {\r\n    min-height: 220px;\r\n    display: grid;\r\n    place-items: center;\r\n    color: #0b1a26;\r\n    font-weight: 900;\r\n}\r\n.qr-amount {\r\n    margin-top: 16px;\r\n    padding: 15px;\r\n    border: 1px solid rgba(155, 211, 61, .24);\r\n    border-radius: 6px;\r\n    background: rgba(12, 32, 26, .78);\r\n}\r\n.qr-amount span {\r\n    color: #9cb5a8;\r\n    font-size: 11px;\r\n    font-weight: 900;\r\n    letter-spacing: .08em;\r\n    text-transform: uppercase;\r\n}\r\n.qr-amount strong {\r\n    display: block;\r\n    margin-top: 6px;\r\n    color: #dfffb5;\r\n    font-size: 30px;\r\n    line-height: 1;\r\n}\r\n.qr-status {\r\n    margin-top: 12px;\r\n    padding: 13px;\r\n    border: 1px solid rgba(255, 205, 110, .22);\r\n    border-radius: 6px;\r\n    background: rgba(255, 205, 110, .07);\r\n}\r\n.qr-status.is-paid {\r\n    border-color: rgba(155, 211, 61, .32);\r\n    background: rgba(155, 211, 61, .09);\r\n}\r\n.qr-status strong {\r\n    display: block;\r\n    color: #ffd88d;\r\n    font-size: 14px;\r\n}\r\n.qr-status.is-paid strong { color: #d6ff9b; }\r\n.qr-status span {\r\n    display: block;\r\n    margin-top: 5px;\r\n    color: #b5c8d8;\r\n    font-size: 12px;\r\n    line-height: 1.45;\r\n}\r\n.transfer-card { padding: 18px; }\r\n.transfer-card h3 {\r\n    margin: 0 0 16px;\r\n    color: #f0f8ff;\r\n    font-size: 20px;\r\n}\r\n.transfer-card dl {\r\n    display: grid;\r\n    grid-template-columns: 130px minmax(0, 1fr);\r\n    gap: 14px 18px;\r\n    margin: 0;\r\n}\r\n.transfer-card dt {\r\n    color: #8ea7b9;\r\n    font-size: 12px;\r\n}\r\n.transfer-card dd {\r\n    margin: 0;\r\n    overflow-wrap: anywhere;\r\n    color: #eef8ff;\r\n    font-size: 13px;\r\n    font-weight: 850;\r\n}\r\n.qr-actions {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: 10px;\r\n    margin-top: 14px;\r\n}\r\n.primary-command,\r\n.secondary-command {\r\n    min-height: 42px;\r\n    padding: 0 16px;\r\n    border-radius: 5px;\r\n    font-size: 12px;\r\n    font-weight: 950;\r\n}\r\n.primary-command {\r\n    border: 1px solid rgba(190, 240, 111, .24);\r\n    background: linear-gradient(180deg, #9bd33d 0%, #75a920 100%);\r\n    color: #fff;\r\n}\r\n.secondary-command {\r\n    border: 1px solid rgba(102, 192, 244, .22);\r\n    background: rgba(102, 192, 244, .08);\r\n    color: #bfeaff;\r\n}\r\n.qr-note {\r\n    margin: 14px 0 0;\r\n    color: #8fa6b8;\r\n    font-size: 12px;\r\n    line-height: 1.45;\r\n}\r\n.app-loading-overlay {\r\n    position: fixed;\r\n    inset: 0;\r\n    z-index: 70;\r\n    display: grid;\r\n    place-items: center;\r\n    background: rgba(3, 8, 13, .62);\r\n    backdrop-filter: blur(8px);\r\n}\r\n.app-loading-dialog {\r\n    width: min(420px, calc(100vw - 48px));\r\n    padding: 24px;\r\n    border: 1px solid rgba(102, 192, 244, .24);\r\n    border-radius: 7px;\r\n    background: linear-gradient(180deg, rgba(16, 35, 52, .98), rgba(7, 17, 26, .98));\r\n    box-shadow: 0 28px 70px rgba(0, 0, 0, .38);\r\n}\r\n.app-loading-kicker {\r\n    color: var(--cyan);\r\n    font-size: 11px;\r\n    font-weight: 950;\r\n    letter-spacing: .16em;\r\n}\r\n.app-loading-dialog h2 { margin: 8px 0 8px; }\r\n.app-loading-dialog p { margin: 0; color: var(--muted); line-height: 1.5; }\r\n@media (max-width: 1120px) {\r\n    .wallet-chrome { grid-template-columns: auto minmax(0, 1fr) auto; }\r\n    .wallet-nav { justify-self: start; }\r\n    .account-menu-shell { display: none; }\r\n    .topup-card { grid-template-columns: 1fr; }\r\n    .qr-dialog-body { grid-template-columns: 1fr; }\r\n}";
	}

	private static string BuildLoadingOverlay()
	{
		return "<div class=\"app-loading-overlay\" data-app-loading hidden>\r\n    <div class=\"app-loading-dialog\" tabindex=\"-1\">\r\n        <span class=\"app-loading-kicker\">NESTG STORE</span>\r\n        <h2 data-app-loading-title>Đang xử lý</h2>\r\n        <p data-app-loading-message>Vui lòng chờ trong giây lát.</p>\r\n    </div>\r\n</div>";
	}

	private static string BuildScript()
	{
		return "(() => {\r\n    const post = message => window.chrome?.webview?.postMessage(message);\r\n" + StoreAccountMenuHtml.Script + "\r\n    const form = document.querySelector('[data-topup-form]');\r\n    const amountInput = form?.elements.namedItem('amount');\r\n    const submitButton = document.querySelector('[data-submit]');\r\n    const status = document.querySelector('[data-status]');\r\n    const quickButtons = document.querySelectorAll('[data-quick-amount]');\r\n    const toastHost = document.querySelector('[data-toast-host]');\r\n    const appLoadingOverlay = document.querySelector('[data-app-loading]');\r\n    const appLoadingTitle = appLoadingOverlay?.querySelector('[data-app-loading-title]');\r\n    const appLoadingMessage = appLoadingOverlay?.querySelector('[data-app-loading-message]');\r\n    const qrModal = document.querySelector('[data-qr-modal]');\r\n    const qrImage = document.querySelector('[data-qr-image]');\r\n    const qrImageFallback = document.querySelector('[data-qr-image-fallback]');\r\n    const qrTotal = document.querySelector('[data-qr-total]');\r\n    const qrStatus = document.querySelector('[data-qr-status]');\r\n    const qrStatusTitle = document.querySelector('[data-qr-status-title]');\r\n    const qrStatusDescription = document.querySelector('[data-qr-status-description]');\r\n    const qrBank = document.querySelector('[data-qr-bank]');\r\n    const qrAccountNumber = document.querySelector('[data-qr-account-number]');\r\n    const qrAccountName = document.querySelector('[data-qr-account-name]');\r\n    const qrTransferContent = document.querySelector('[data-qr-transfer-content]');\r\n    const qrOrderCode = document.querySelector('[data-qr-order-code]');\r\n    const qrExpires = document.querySelector('[data-qr-expires]');\r\n    const qrRefreshButton = document.querySelector('[data-qr-refresh]');\r\n    const paymentSuccess = document.querySelector('[data-payment-success]');\r\n    const paymentSuccessTitle = document.querySelector('[data-payment-success-title]');\r\n    const paymentSuccessMessage = document.querySelector('[data-payment-success-message]');\r\n    const paymentSuccessBalance = document.querySelector('[data-payment-success-balance]');\r\n    const paymentSuccessConfirm = document.querySelector('[data-payment-success-confirm]');\r\n    const minimumAmount = Number(document.body.dataset.minAmount || 0);\r\n    const maximumAmount = Number(document.body.dataset.maxAmount || 0);\r\n    const formatter = new Intl.NumberFormat('vi-VN');\r\n    let activeCheckoutOrderCode = '';\r\n    let qrPollTimer = 0;\r\n\r\n    function parseAmount(value) {\r\n        const digits = String(value || '').replace(/\\D/g, '');\r\n        return digits ? Number(digits) : 0;\r\n    }\r\n\r\n    function formatAmount(value) {\r\n        return formatter.format(Math.max(0, Number(value) || 0));\r\n    }\r\n\r\n    function setStatus(message = '', isError = false) {\r\n        if (!status) return;\r\n        status.textContent = message;\r\n        status.classList.toggle('is-error', Boolean(isError));\r\n    }\r\n\r\n    function setBusy(isBusy, message = '', isError = false) {\r\n        if (submitButton) {\r\n            submitButton.disabled = isBusy;\r\n            submitButton.textContent = isBusy ? 'Đang tạo QR...' : 'Tạo phiếu nạp tiền';\r\n        }\r\n        if (amountInput) amountInput.disabled = isBusy;\r\n        quickButtons.forEach(button => button.disabled = isBusy);\r\n        setStatus(message, isError);\r\n    }\r\n\r\n    function showToast(message) {\r\n        if (!toastHost || !message) return;\r\n        const toast = document.createElement('div');\r\n        toast.className = 'toast';\r\n        toast.textContent = message;\r\n        toastHost.append(toast);\r\n        window.setTimeout(() => toast.remove(), 3400);\r\n    }\r\n\r\n    window.__nestgHome = {\r\n        setCartCount() {},\r\n        toast: showToast\r\n    };\r\n\r\n    window.__nestgWalletTopUp = {\r\n        setBusy,\r\n        showQrPopup(payload) {\r\n            showQrPopup(payload);\r\n        },\r\n        updateQrStatus(payload) {\r\n            updateQrStatus(payload);\r\n        },\r\n        showSuccess(payload) {\r\n            showSuccess(payload);\r\n        },\r\n        focus() {\r\n            amountInput?.focus();\r\n        }\r\n    };\r\n\r\n    window.__nestgLoading = {\r\n        show(title, message) {\r\n            document.body.classList.add('app-loading-active');\r\n            if (appLoadingTitle && title) appLoadingTitle.textContent = title;\r\n            if (appLoadingMessage && message) appLoadingMessage.textContent = message;\r\n            if (appLoadingOverlay) appLoadingOverlay.hidden = false;\r\n        },\r\n        hide() {\r\n            document.body.classList.remove('app-loading-active');\r\n            if (appLoadingOverlay) appLoadingOverlay.hidden = true;\r\n        }\r\n    };\r\n\r\n    quickButtons.forEach(button => {\r\n        button.addEventListener('click', () => {\r\n            const amount = Number(button.getAttribute('data-quick-amount') || 0);\r\n            if (amountInput) {\r\n                amountInput.value = formatAmount(amount);\r\n                amountInput.focus();\r\n            }\r\n            quickButtons.forEach(item => item.classList.toggle('is-selected', item === button));\r\n            setStatus('');\r\n        });\r\n    });\r\n\r\n    amountInput?.addEventListener('input', () => {\r\n        const amount = parseAmount(amountInput.value);\r\n        amountInput.value = amount ? formatAmount(amount) : '';\r\n        quickButtons.forEach(button => {\r\n            button.classList.toggle('is-selected', Number(button.getAttribute('data-quick-amount') || 0) === amount);\r\n        });\r\n    });\r\n\r\n    form?.addEventListener('submit', event => {\r\n        event.preventDefault();\r\n        const amount = parseAmount(amountInput?.value);\r\n        if (amount <= 0) {\r\n            setStatus('Vui lòng nhập số tiền cần nạp.', true);\r\n            amountInput?.focus();\r\n            return;\r\n        }\r\n        if (minimumAmount > 0 && amount < minimumAmount) {\r\n            setStatus(`Số tiền nạp tối thiểu là ${formatAmount(minimumAmount)} VND.`, true);\r\n            amountInput?.focus();\r\n            return;\r\n        }\r\n        if (maximumAmount > 0 && amount > maximumAmount) {\r\n            setStatus(`Mỗi lần nạp tối đa ${formatAmount(maximumAmount)} VND.`, true);\r\n            amountInput?.focus();\r\n            return;\r\n        }\r\n\r\n        setBusy(true);\r\n        post({ type: 'submitWalletTopup', amount: String(amount) });\r\n    });\r\n\r\n    function setText(element, value) {\r\n        if (element) element.textContent = value || '';\r\n    }\r\n\r\n    function updateQrStatus(payload) {\r\n        if (!payload) return;\r\n        setText(qrStatusTitle, payload.statusTitle || '');\r\n        setText(qrStatusDescription, payload.statusDescription || '');\r\n        qrStatus?.classList.toggle('is-paid', Boolean(payload.isPaid));\r\n        if (payload.isPaid) {\r\n            window.clearInterval(qrPollTimer);\r\n            qrPollTimer = 0;\r\n            if (qrRefreshButton) {\r\n                qrRefreshButton.disabled = true;\r\n                qrRefreshButton.textContent = 'Đã thanh toán';\r\n            }\r\n            showToast('Nạp ví thành công. Số dư sẽ được cập nhật sau khi đóng popup.');\r\n        } else if (qrRefreshButton) {\r\n            qrRefreshButton.disabled = false;\r\n            qrRefreshButton.textContent = 'Làm mới trạng thái';\r\n        }\r\n    }\r\n\r\n    function showQrPopup(payload) {\r\n        if (!qrModal || !payload) return;\r\n        if (paymentSuccess) paymentSuccess.hidden = true;\r\n        activeCheckoutOrderCode = payload.orderCode || '';\r\n        setText(qrTotal, payload.totalAmountText || '');\r\n        setText(qrBank, payload.bankName || '');\r\n        setText(qrAccountNumber, payload.accountNumber || '');\r\n        setText(qrAccountName, payload.accountName || '');\r\n        setText(qrTransferContent, payload.transferContent || '');\r\n        setText(qrOrderCode, payload.transferContent || '');\r\n        setText(qrExpires, payload.expiresAtText || 'Không giới hạn');\r\n        updateQrStatus(payload);\r\n\r\n        if (qrImage) {\r\n            qrImage.hidden = !payload.qrImageUrl;\r\n            qrImage.src = payload.qrImageUrl || '';\r\n        }\r\n        if (qrImageFallback) {\r\n            qrImageFallback.hidden = Boolean(payload.qrImageUrl);\r\n        }\r\n\r\n        qrModal.hidden = false;\r\n        document.body.style.overflow = 'hidden';\r\n        window.clearInterval(qrPollTimer);\r\n        if (!payload.isPaid && activeCheckoutOrderCode) {\r\n            qrPollTimer = window.setInterval(() => {\r\n                post({ type: 'refreshWalletTopupStatus', orderCode: activeCheckoutOrderCode });\r\n            }, 5000);\r\n        }\r\n    }\r\n\r\n    function showSuccess(payload) {\r\n        window.clearInterval(qrPollTimer);\r\n        qrPollTimer = 0;\r\n        if (!qrModal || !paymentSuccess) return;\r\n        setText(paymentSuccessTitle, payload?.title || 'Bạn đã thanh toán thành công');\r\n        setText(paymentSuccessMessage, payload?.message || 'Tiền đã được cộng vào ví NestG của bạn.');\r\n        setText(paymentSuccessBalance, payload?.walletBalanceText || '');\r\n        paymentSuccess.hidden = false;\r\n        qrModal.hidden = false;\r\n        document.body.style.overflow = 'hidden';\r\n        paymentSuccessConfirm?.focus();\r\n    }\r\n\r\n    function closeQrPopup() {\r\n        window.clearInterval(qrPollTimer);\r\n        qrPollTimer = 0;\r\n        if (qrModal) qrModal.hidden = true;\r\n        document.body.style.overflow = '';\r\n        post({ type: 'closeWalletTopupPopup' });\r\n    }\r\n\r\n    document.querySelectorAll('[data-qr-close]').forEach(button => {\r\n        button.addEventListener('click', closeQrPopup);\r\n    });\r\n\r\n    qrRefreshButton?.addEventListener('click', () => {\r\n        if (!activeCheckoutOrderCode) return;\r\n        qrRefreshButton.disabled = true;\r\n        qrRefreshButton.textContent = 'Đang kiểm tra...';\r\n        post({ type: 'refreshWalletTopupStatus', orderCode: activeCheckoutOrderCode });\r\n    });\r\n\r\n    paymentSuccessConfirm?.addEventListener('click', () => {\r\n        paymentSuccessConfirm.disabled = true;\r\n        paymentSuccessConfirm.textContent = 'Đang xác thực...';\r\n        post({ type: 'confirmWalletTopupSuccess', orderCode: activeCheckoutOrderCode });\r\n    });\r\n\r\n    qrImage?.addEventListener('error', () => {\r\n        qrImage.hidden = true;\r\n        if (qrImageFallback) qrImageFallback.hidden = false;\r\n    });\r\n\r\n    function isInteractive(target) {\r\n        return Boolean(target.closest('button, input, textarea, select, a, [data-host-action], [data-qr-modal]'));\r\n    }\r\n\r\n    document.addEventListener('pointerdown', event => {\r\n        const target = event.target instanceof Element ? event.target : null;\r\n        if (!target || isInteractive(target)) return;\r\n        if (target.closest('[data-drag-region]')) {\r\n            post({ type: 'dragWindow' });\r\n        }\r\n    });\r\n\r\n    document.addEventListener('click', event => {\r\n        const rawTarget = event.target instanceof Element ? event.target : null;\r\n        if (!rawTarget) return;\r\n        if (rawTarget.closest('[data-account-toggle]')) {\r\n            setAccountMenuOpen(Boolean(accountMenu?.hidden));\r\n            return;\r\n        }\r\n        if (!rawTarget.closest('[data-account-menu]')) {\r\n            setAccountMenuOpen(false);\r\n        }\r\n\r\n        const target = rawTarget.closest('[data-host-action]');\r\n        if (!target) return;\r\n        event.preventDefault();\r\n        event.stopPropagation();\r\n        post({ type: target.getAttribute('data-host-action') });\r\n    });\r\n\r\n    window.requestAnimationFrame(() => amountInput?.focus());\r\n})();";
	}

	private static string FormatAmount(decimal amount)
	{
		return string.Format(ViVnCulture, "{0:N0} đ", Math.Max(0m, amount));
	}

	private static string Initial(string? value)
	{
		return Html((string.IsNullOrWhiteSpace(value) ? "N" : value.Trim()).Substring(0, 1).ToUpperInvariant());
	}

	private static string Html(string? value)
	{
		return WebUtility.HtmlEncode(value ?? string.Empty);
	}
}
